package say

import (
	"fmt"
	"strings"
)

// Say spells out a number from 0 to 999,999,999,999 in English.
// It returns ok=false if the number is outside that range.
func Say(n int64) (string, bool) {
	if n < 0 || n > 999999999999 {
		return "", false
	}
	if n == 0 {
		return "zero", true
	}

	chunks := make([]int, 0, 4)
	for n > 0 {
		chunks = append(chunks, int(n%1000))
		n /= 1000
	}

	scales := []string{"", " thousand", " million", " billion"}
	parts := make([]string, 0, len(chunks))
	for i := len(chunks) - 1; i >= 0; i-- {
		if c := chunks[i]; c != 0 {
			parts = append(parts, belowThousand(c)+scales[i])
		}
	}
	return strings.Join(parts, " "), true
}

var ones = []string{
	"zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
	"ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
	"seventeen", "eighteen", "nineteen",
}

var tens = []string{
	"", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
}

// belowThousand spells out a number from 1 to 999.
func belowThousand(n int) string {
	var sb strings.Builder
	if n >= 100 {
		fmt.Fprintf(&sb, "%s hundred", ones[n/100])
		n %= 100
		if n != 0 {
			sb.WriteByte(' ')
		}
	}
	if n >= 20 {
		fmt.Fprintf(&sb, "%s-%s", tens[n/10], ones[n%10])
	} else if n > 0 {
		sb.WriteString(ones[n])
	}
	return sb.String()
}

